import { useState, useRef, useEffect } from "react";
import Logo from "./Logo";
import { useROICanvas } from "../hooks/useCanvas";

const PROCESSING_STEPS = [
  "Decomposing spatial frequencies...",
  "Extracting local phase per sub-band...",
  "Applying Butterworth band-pass filter...",
  "Amplifying phase components...",
  "Reconstructing frames...",
  "Running FFT vibration analysis...",
  "Identifying dominant frequency...",
  "Generating report..."
];

const PRESETS = [
  {
    id: "engine",
    name: "Engine / Motor",
    tag: "10-200 Hz",
    desc: "Rotating machinery"
  },
  {
    id: "structural",
    name: "Structural Flex",
    tag: "0.1-50 Hz",
    desc: "Buildings & bridges"
  },
  {
    id: "custom",
    name: "Custom Range",
    tag: "User-defined",
    desc: "Manual Hz input"
  }
];

const SETTINGS = [
  {
    name: "Amplification Factor",
    hint: "Recommended",
    value: "8x"
  },
  {
    name: "Temporal Filter",
    hint: "Bandpass",
    value: "Ideal BPF"
  },
  {
    name: "Frame Sampling",
    hint: "Auto-detected",
    value: "30 fps"
  },
  {
    name: "Color Map",
    hint: "Displacement",
    value: "Jet (HSV)"
  }
];

function ProcessingOverlay() {
  const [step, setStep] = useState(0);
  const [progress, setProgress] = useState(0);

  useEffect(() => {
    const total = 3800;
    const interval = total / PROCESSING_STEPS.length;

    let elapsed = 0;
    let stepIndex = 0;

    const timer = setInterval(() => {
      elapsed += interval;

      const percentage = Math.min(
        (elapsed / total) * 100,
        100
      );

      setProgress(percentage);

      if (stepIndex < PROCESSING_STEPS.length) {
        setStep(stepIndex);
        stepIndex += 1;
      }

      if (elapsed >= total) {
        clearInterval(timer);
      }
    }, interval);

    return () => {
      clearInterval(timer);
    };
  }, []);

  return (
    <div className="processing-overlay">
      <div className="processing-card">

        <div className="processing-spinner">
          <svg
            width="56"
            height="56"
            viewBox="0 0 56 56"
          >
            <circle
              cx="28"
              cy="28"
              r="24"
              stroke="#e5e7eb"
              strokeWidth="3"
              fill="none"
            />

            <circle
              cx="28"
              cy="28"
              r="24"
              stroke="#E8741A"
              strokeWidth="3"
              fill="none"
              strokeDasharray="100 50"
              strokeLinecap="round"
            >
              <animateTransform
                attributeName="transform"
                type="rotate"
                from="0 28 28"
                to="360 28 28"
                dur="1s"
                repeatCount="indefinite"
              />
            </circle>
          </svg>
        </div>

        <h3 className="processing-title">
          Analyzing Motion
        </h3>

        <p className="processing-sub">
          {PROCESSING_STEPS[step]}
        </p>

        <div className="processing-bar-wrap">
          <div
            className="processing-bar-fill"
            style={{
              width: progress + "%"
            }}
          />
        </div>

      </div>
    </div>
  );
}

export default function UploadPage(props) {
  const [file, setFile] = useState(null);
  const [videoURL, setVideoURL] = useState(null);
  const [isDragging, setIsDragging] = useState(false);

  const [preset, setPreset] = useState("engine");
  const [showCustom, setShowCustom] = useState(false);

  const [minHz, setMinHz] = useState("");
  const [maxHz, setMaxHz] = useState("");

  const [processing, setProcessing] = useState(false);

  const fileInputRef = useRef(null);
  const roiCanvasRef = useROICanvas();

  // Load selected video
  const loadVideo = (selectedFile) => {
    if (!selectedFile) {
      return;
    }

    setFile(selectedFile);

    if (videoURL) {
      URL.revokeObjectURL(videoURL);
    }

    const newURL = URL.createObjectURL(selectedFile);
    setVideoURL(newURL);
  };

  // Handle drag and drop
  const handleDrop = (event) => {
    event.preventDefault();
    setIsDragging(false);

    const droppedFile = event.dataTransfer.files[0];

    if (
      droppedFile &&
      droppedFile.type.startsWith("video/")
    ) {
      loadVideo(droppedFile);
    } else {
      alert("Please select a valid video file.");
    }
  };

  // Handle normal file selection
  const handleFileSelect = (event) => {
    const selectedFile = event.target.files[0];

    if (selectedFile) {
      loadVideo(selectedFile);
    }
  };

  // Select frequency preset
  const selectPreset = (id) => {
    setPreset(id);

    if (id === "custom") {
      setShowCustom(true);
    } else {
      setShowCustom(false);
    }
  };

  // Remove uploaded video
  const removeVideo = () => {
    if (videoURL) {
      URL.revokeObjectURL(videoURL);
    }

    setFile(null);
    setVideoURL(null);

    if (fileInputRef.current) {
      fileInputRef.current.value = "";
    }
  };

  // Start analysis
  const startAnalysis = async () => {
    if (!file) {
      alert("Please upload a video first.");
      return;
    }

    // Validate custom frequency before starting
    if (preset === "custom") {
      if (
        !minHz ||
        !maxHz ||
        Number(minHz) >= Number(maxHz)
      ) {
        alert(
          "Please enter valid minimum and maximum Hz values."
        );
        return;
      }
    }

    setProcessing(true);

    try {
      // ==========================================
      // STEP 1: Upload video
      // ==========================================

      const formData = new FormData();
      formData.append("file", file);

      console.log("Uploading video...");

      const uploadResponse = await fetch(
        "http://127.0.0.1:8000/api/upload",
        {
          method: "POST",
          body: formData
        }
      );

      if (!uploadResponse.ok) {
        throw new Error(
          "Video upload failed. Status: " +
          uploadResponse.status
        );
      }

      const uploadResult =
        await uploadResponse.json();

      console.log(
        "Upload response:",
        uploadResult
      );

      // ==========================================
      // STEP 2: Get Job ID
      // ==========================================

      const jobId =
        uploadResult.job_id ||
        uploadResult.id ||
        uploadResult;

      if (!jobId) {
        throw new Error(
          "Backend did not return a job ID."
        );
      }

      console.log(
        "Created Job ID:",
        jobId
      );

      // ==========================================
      // STEP 3: Determine frequency range
      // ==========================================

      let lowHz = 10;
      let highHz = 200;

      if (preset === "structural") {
        lowHz = 0.1;
        highHz = 50;
      }

      if (preset === "custom") {
        lowHz = Number(minHz);
        highHz = Number(maxHz);
      }

      console.log(
        "Frequency range:",
        lowHz,
        "-",
        highHz,
        "Hz"
      );

      // ==========================================
      // STEP 4: Submit ROI and settings
      // ==========================================

      const roiData = {
        x: 0,
        y: 0,
        w: 1,
        h: 1,
        preset: preset,
        low_hz: lowHz,
        high_hz: highHz,
        alpha: 8
      };

      console.log(
        "Sending ROI:",
        roiData
      );

      const roiResponse = await fetch(
        "http://127.0.0.1:8000/api/jobs/" +
          jobId +
          "/roi",
        {
          method: "POST",
          headers: {
            "Content-Type": "application/json"
          },
          body: JSON.stringify(roiData)
        }
      );

      if (!roiResponse.ok) {
        throw new Error(
          "ROI submission failed. Status: " +
          roiResponse.status
        );
      }

      const roiResult =
        await roiResponse.json();

      console.log(
        "ROI response:",
        roiResult
      );

      // ==========================================
      // STEP 5: Start backend processing
      // ==========================================

      console.log(
        "Starting ML processing..."
      );

      const processResponse = await fetch(
        "http://127.0.0.1:8000/api/jobs/" +
          jobId +
          "/process",
        {
          method: "POST"
        }
      );

      if (!processResponse.ok) {
        throw new Error(
          "Processing request failed. Status: " +
          processResponse.status
        );
      }

      const processResult =
        await processResponse.json();

      console.log(
        "Processing response:",
        processResult
      );

      // ==========================================
      // STEP 6: Save analysis information
      // ==========================================

      const analysisData = {
        job_id: jobId,
        upload: uploadResult,
        roi: roiResult,
        process: processResult,
        file_name: file.name,
        preset: preset,
        low_hz: lowHz,
        high_hz: highHz,
        alpha: 8
      };

      sessionStorage.setItem(
        "motionAmpResult",
        JSON.stringify(analysisData)
      );

      console.log(
        "Analysis completed:",
        analysisData
      );

      setProcessing(false);

      // ==========================================
      // STEP 7: Move to Results page
      // ==========================================

      if (props.onAnalysisComplete) {
        props.onAnalysisComplete(
          analysisData
        );
      }

    } catch (error) {
      console.error(
        "Motion AMP backend error:",
        error
      );

      setProcessing(false);

      alert(
        "Motion AMP processing failed.\n\n" +
        error.message
      );
    }
  };

  // Dropzone CSS class
  let dropzoneClass = "dropzone";

  if (isDragging) {
    dropzoneClass =
      "dropzone dropzone--drag";
  }

  // Start button CSS class
  let startButtonClass = "btn-start";

  if (file) {
    startButtonClass =
      "btn-start btn-start--active";
  }

  return (
    <div className="upload-page page-enter">

      {/* NAVBAR */}

      <nav className="navbar navbar--light">

        <div className="nav-inner">

          <button
            className="btn-back"
            onClick={() =>
              props.onNavigate("landing")
            }
          >
            ← Back
          </button>

          <Logo
            onClick={() =>
              props.onNavigate("landing")
            }
          />

          <span className="step-indicator">
            STEP 1 OF 2 — UPLOAD
          </span>

        </div>

      </nav>

      <div className="upload-layout">

        {/* LEFT SIDE */}

        <div className="upload-main">

          <div className="upload-header">

            <h1 className="upload-title">
              Upload Video
            </h1>

            <p className="upload-subtitle">
              Upload a video of the target
              structure or component for
              motion amplification analysis
            </p>

          </div>

          {/* VIDEO DROPZONE */}

          <div
            className={dropzoneClass}
            onClick={() => {
              if (!videoURL) {
                fileInputRef.current?.click();
              }
            }}
            onDragOver={(event) => {
              event.preventDefault();
              setIsDragging(true);
            }}
            onDragLeave={() => {
              setIsDragging(false);
            }}
            onDrop={handleDrop}
          >

            <input
              ref={fileInputRef}
              type="file"
              accept="video/*"
              style={{
                display: "none"
              }}
              onChange={handleFileSelect}
            />

            {!videoURL && (
              <div className="dropzone-content">

                <div className="drop-icon">

                  <svg
                    width="36"
                    height="36"
                    viewBox="0 0 24 24"
                    fill="none"
                    stroke="#9ca3af"
                    strokeWidth="1.5"
                    strokeLinecap="round"
                  >

                    <polyline
                      points="16 16 12 12 8 16"
                    />

                    <line
                      x1="12"
                      y1="12"
                      x2="12"
                      y2="21"
                    />

                    <path
                      d="M20.39 18.39A5 5 0 0 0 18 9h-1.26A8 8 0 1 0 3 16.3"
                    />

                  </svg>

                </div>

                <p className="drop-main">
                  Drag &amp; drop your video
                </p>

                <p className="drop-sub">
                  or click to browse files
                </p>

                <p className="drop-formats">
                  MP4 • MOV • AVI • MKV —
                  Up to 2 GB
                </p>

              </div>
            )}

            {videoURL && (
              <div
                className="dropzone-preview"
                onClick={(event) => {
                  event.stopPropagation();
                }}
              >

                <video
                  src={videoURL}
                  controls
                  playsInline
                  preload="metadata"
                />

                <div className="file-info">

                  {file.name}

                  {" · "}

                  {(file.size /
                    (1024 * 1024)
                  ).toFixed(1)}

                  {" MB "}

                  <button
                    type="button"
                    style={{
                      background: "none",
                      border: "none",
                      color: "#E8741A",
                      cursor: "pointer",
                      fontSize: 12
                    }}
                    onClick={removeVideo}
                  >
                    Remove
                  </button>

                </div>

              </div>
            )}

          </div>

          {/* ROI SECTION */}

          <div className="roi-section">

            <div className="roi-header">

              <div>

                <h3 className="roi-title">
                  Region of Interest
                </h3>

                <p className="roi-sub">
                  Select the area to focus
                  analysis on
                </p>

              </div>

              <span className="roi-tag">
                Full Frame
              </span>

            </div>

            <div className="roi-canvas-wrap">

              <canvas
                ref={roiCanvasRef}
                className="roi-canvas"
                height={280}
              />

              <div className="roi-hint">
                Drag handles to adjust
              </div>

            </div>

          </div>

        </div>

        {/* RIGHT SIDEBAR */}

        <div className="upload-sidebar">

          {/* FREQUENCY PRESET */}

          <div className="sidebar-card">

            <h3 className="sidebar-title">
              Frequency Preset
            </h3>

            <p className="sidebar-sub">
              Select target vibration range
            </p>

            <div className="preset-list">

              {PRESETS.map((item) => (

                <div
                  key={item.id}
                  className={
                    preset === item.id
                      ? "preset-item preset-item--active"
                      : "preset-item"
                  }
                  onClick={() =>
                    selectPreset(item.id)
                  }
                >

                  <div className="preset-info">

                    <span className="preset-name">
                      {item.name}
                    </span>

                    <span className="preset-tag">
                      {item.tag}
                    </span>

                  </div>

                  <span className="preset-desc">
                    {item.desc}
                  </span>

                </div>

              ))}

              {showCustom && (

                <div className="custom-range-inputs">

                  <div className="custom-input-row">

                    <div className="custom-input-group">

                      <label>
                        Min Hz
                      </label>

                      <input
                        type="number"
                        placeholder="e.g. 5"
                        value={minHz}
                        onChange={(event) => {
                          setMinHz(
                            event.target.value
                          );
                        }}
                      />

                    </div>

                    <div className="custom-input-group">

                      <label>
                        Max Hz
                      </label>

                      <input
                        type="number"
                        placeholder="e.g. 100"
                        value={maxHz}
                        onChange={(event) => {
                          setMaxHz(
                            event.target.value
                          );
                        }}
                      />

                    </div>

                  </div>

                </div>

              )}

            </div>

          </div>

          {/* ANALYSIS SETTINGS */}

          <div className="sidebar-card">

            <h3 className="sidebar-title">
              Analysis Settings
            </h3>

            <div className="settings-list">

              {SETTINGS.map((setting) => (

                <div
                  key={setting.name}
                  className="setting-row"
                >

                  <div>

                    <span className="setting-name">
                      {setting.name}
                    </span>

                    <span className="setting-hint">
                      {setting.hint}
                    </span>

                  </div>

                  <span className="setting-value">
                    {setting.value}
                  </span>

                </div>

              ))}

            </div>

          </div>

          {/* START BUTTON */}

          <button
            type="button"
            className={startButtonClass}
            onClick={startAnalysis}
            disabled={!file || processing}
          >

            {processing &&
              "Processing..."}

            {!processing &&
              file &&
              "Start Analysis"}

            {!processing &&
              !file &&
              "Upload a Video to Continue"}

          </button>

        </div>

      </div>

      {/* PROCESSING OVERLAY */}

      {processing && (
        <ProcessingOverlay />
      )}

    </div>
  );
}
